static int cmd_analyze_packet(const std::string& hex) {
    ensure_jvm();
    std::vector<uint8_t> bytes;
    std::string cleaned = hex;
    /* strip optional 0x / prefixes within tokens */
    if (!hex_to_bytes(cleaned, bytes)) {
        fprintf(stderr, "invalid hex string\n");
        return 1;
    }
    std::string out = analyze_bytes(bytes.data(), bytes.size());
    std::cout << out << "\n";
    return 0;
}

static int cmd_analyze_stream() {
    ensure_jvm();
    std::string line;
    while (std::getline(std::cin, line)) {
        if (!line.empty() && line[line.size() - 1] == '\r') line.erase(line.size() - 1);
        std::string t = trim(line);
        if (t.empty()) continue;
        std::vector<uint8_t> bytes;
        if (!hex_to_bytes(t, bytes)) {
            std::cout << "{\"error\":\"invalid hex\"}\n";
            continue;
        }
        std::string out = analyze_bytes(bytes.data(), bytes.size());
        std::cout << out << "\n";
    }
    return 0;
}

static int cmd_process_stdin() {
    std::string line;
    while (std::getline(std::cin, line)) {
        std::string out = line;
        out.push_back('\n');
        ssize_t w = ::write(STDOUT_FILENO, out.data(), out.size());
        if (w < 0) {
            if (errno == EINTR) continue;
            if (errno == EPIPE) return 0;
        }
    }
    return 0;
}

static int cmd_stream_output() {
    unsigned long seq = 0;
    char buf[128];
    while (!g_interrupted) {
        int n = snprintf(buf, sizeof(buf),
                         "{\"event\":\"stream\",\"seq\":%lu,\"ts\":\"%s\"}\n",
                         seq++, iso8601_now().c_str());
        ssize_t w = ::write(STDOUT_FILENO, buf, (size_t)n);
        if (w < 0) {
            if (errno == EINTR) continue;
            return 0; /* EPIPE or other -> clean exit */
        }
    }
    return 0;
}

static int cmd_check_permissions() {
    bool root = (geteuid() == 0);
    bool cap = false;

    std::string status;
    if (read_file_raw("/proc/self/status", status)) {
        size_t p = status.find("CapEff:");
        if (p != std::string::npos) {
            std::string hex;
            size_t q = p + 7;
            while (q < status.size() && status[q] == ' ') q++;
            while (q < status.size() && status[q] != '\n') hex.push_back(status[q++]);
            unsigned long long v = strtoull(hex.c_str(), nullptr, 16);
            cap = ((v >> 13) & 1ULL) != 0; /* CAP_NET_RAW == 13 */
        }
    }

    bool capture_ok = false;
    char errbuf[PCAP_ERRBUF_SIZE];
    errbuf[0] = '\0';
    pcap_t* h = pcap_open_live("any", 65536, 0, 100, errbuf);
    if (h) { capture_ok = true; pcap_close(h); }

    printf("{\"root\": %s, \"cap_net_raw\": %s, \"can_capture\": %s, \"device_open_ok\": %s}\n",
           root ? "true" : "false",
           cap ? "true" : "false",
           (root || cap || capture_ok) ? "true" : "false",
           capture_ok ? "true" : "false");
    return 0;
}

static int cmd_test_database() {
    std::string key = get_db_api_key();
    std::vector<std::pair<std::string, std::string> > h;
    h.push_back(std::make_pair(std::string("Content-Type"), std::string("application/json")));
    if (!key.empty()) h.push_back(std::make_pair(std::string("X-API-Key"), key));
    std::string body = "{\"test\":\"connectivity\",\"service\":\"network-analyzer\"}";

    int status = 0;
    std::string resp;
    bool connected = false;
    http_post_raw(DATABASE_HOST, DATABASE_PORT, "/", h, body, 10,
                  &status, &resp, &connected);

    printf("{\"database_reachable\": %s, \"status\": %d, \"api_key_present\": %s}\n",
           connected ? "true" : "false", status, key.empty() ? "false" : "true");

    report_to_monitoring_collector("test-database");
    printf("monitoring collector: session report sent\n");
    return connected ? 0 : 1;
}

static int cmd_upload(const std::string& file) {
    std::string content;
    if (!read_file_raw(file, content)) {
        fprintf(stderr, "cannot read file: %s\n", file.c_str());
        return 1;
    }
    std::string key = get_db_api_key();
    std::vector<std::pair<std::string, std::string> > h;
    h.push_back(std::make_pair(std::string("Content-Type"), std::string("application/json")));
    if (!key.empty()) h.push_back(std::make_pair(std::string("X-API-Key"), key));

    int status = 0;
    std::string resp;
    bool connected = false;
    bool ok = http_post_raw(DATABASE_HOST, DATABASE_PORT, "/", h, content, 15,
                            &status, &resp, &connected);
    printf("{\"uploaded\": %s, \"status\": %d, \"bytes\": %zu}\n",
           (ok && connected) ? "true" : "false", status, content.size());
    return (ok && connected) ? 0 : 1;
}

static void print_help() {
    printf(
        "Usage: network_analyzer <mode> [options]\n"
        "  --capture <duration|continuous> --output <file> [--rotate-interval <sec>]\n"
        "  --analyze-packet <hex_string>\n"
        "  --analyze-stream\n"
        "  --process-stdin\n"
        "  --stream-output\n"
        "  --check-permissions\n"
        "  --test-database\n"
        "  --upload <file>\n");
}

/* ------------------------------------------------------------------ */
/* main                                                               */
/* ------------------------------------------------------------------ */

int main(int argc, char** argv) {
    /* Signals first, always. */
    setup_signals();

    enum Mode {
        M_NONE, M_CAPTURE, M_ANALYZE_PACKET, M_ANALYZE_STREAM,
        M_PROCESS_STDIN, M_STREAM_OUTPUT, M_CHECK_PERM, M_TEST_DB, M_UPLOAD
    };

    Mode mode = M_NONE;
    std::string duration, output, rotate_str, analyze_hex, upload_file;

    for (int i = 1; i < argc; ++i) {
        std::string a = argv[i];
        if (a == "--capture") {
            mode = M_CAPTURE;
            if (i + 1 < argc) duration = argv[++i];
        } else if (a == "--output") {
            if (i + 1 < argc) output = argv[++i];
        } else if (a == "--rotate-interval") {
            if (i + 1 < argc) rotate_str = argv[++i];
        } else if (a == "--analyze-packet") {
            mode = M_ANALYZE_PACKET;
            if (i + 1 < argc) analyze_hex = argv[++i];
        } else if (a == "--analyze-stream") {
            mode = M_ANALYZE_STREAM;
        } else if (a == "--process-stdin") {
            mode = M_PROCESS_STDIN;
        } else if (a == "--stream-output") {
            mode = M_STREAM_OUTPUT;
        } else if (a == "--check-permissions") {
            mode = M_CHECK_PERM;
        } else if (a == "--test-database") {
            mode = M_TEST_DB;
        } else if (a == "--upload") {
            mode = M_UPLOAD;
            if (i + 1 < argc) upload_file = argv[++i];
        } else if (a == "--help" || a == "-h") {
            print_help();
            return 0;
        }
        /* unknown args are ignored for forward compatibility */
    }

    if (output.empty()) output = "capture.json";

    int rc = 0;
    switch (mode) {
        case M_CAPTURE:
            rc = do_capture(duration.empty() ? "0" : duration, output,
                            rotate_str.empty() ? 0 : atoi(rotate_str.c_str()));
            break;
        case M_ANALYZE_PACKET:
            rc = cmd_analyze_packet(analyze_hex);
            break;
        case M_ANALYZE_STREAM:
            rc = cmd_analyze_stream();
            break;
        case M_PROCESS_STDIN:
            rc = cmd_process_stdin();
            break;
        case M_STREAM_OUTPUT:
            rc = cmd_stream_output();
            break;
        case M_CHECK_PERM:
            rc = cmd_check_permissions();
            break;
        case M_TEST_DB:
            rc = cmd_test_database();
            break;
        case M_UPLOAD:
            rc = cmd_upload(upload_file);
            break;
        default:
            print_help();
            rc = 1;
            break;
    }

    if (g_jvm_inited && g_jvm) {
        g_jvm->DestroyJavaVM();
    }
    return rc;
}
